import{_ as o,C as i,o as n,c as r,j as t,a as s,E as d,al as c}from"./chunks/framework.7vp1BMOE.js";const S=JSON.parse('{"title":"Serial Passthrough (MAVLink SERIAL_CONTROL)","description":"","frontmatter":{},"headers":[],"relativePath":"en/uart/serial_passthrough.md","filePath":"en/uart/serial_passthrough.md"}'),l={name:"en/uart/serial_passthrough.md"};function h(p,e,g,u,b,m){const a=i("Badge");return n(),r("div",null,[e[0]||(e[0]=t("h1",{id:"serial-passthrough-mavlink-serial-control",tabindex:"-1"},[s("Serial Passthrough (MAVLink SERIAL_CONTROL) "),t("a",{class:"header-anchor",href:"#serial-passthrough-mavlink-serial-control","aria-label":'Permalink to "Serial Passthrough (MAVLink SERIAL_CONTROL)"'},"​")],-1)),d(a,{type:"tip",text:"PX4 v1.18"}),e[1]||(e[1]=c(`<p>Serial Passthrough allows a MAVLink client to read from and write to selected flight controller serial interfaces using the <a href="https://mavlink.io/en/messages/common.html#SERIAL_CONTROL" target="_blank" rel="noreferrer">SERIAL_CONTROL</a> message. Typical use cases include: providing a direct serial channel for ESC configuration tools, and debugging serial peripherals over a telemetry link.</p><p>Two cases are supported:</p><ul><li>Control of normal ports, such as telemetry or GPS ports. This works automatically as long as the <a href="./../modules/modules_driver#serialpassthrough"><code>serialpassthrough</code> driver</a> is present in firmware.</li><li>Control of ESC signal pins on STM32F7/H7 boards via a bit-bang UART implemented in software. This requires additional configuration.</li></ul><p>When serial control is enabled/supported, passthrough is automatic. If <code>SERIAL_CONTROL</code> traffic is sent to a supported target, PX4 starts handling that target and returns reply data over MAVLink. You can also start and stop passthrough manually from the PX4 shell.</p><h2 id="device-ids" tabindex="-1">Device IDs <a class="header-anchor" href="#device-ids" aria-label="Permalink to &quot;Device IDs&quot;">​</a></h2><p>The <code>SERIAL_CONTROL.device</code> field selects the target UART that is to be controlled. The following device IDs are allowed (note that this is a subset of the IDs specified in <a href="https://mavlink.io/en/messages/common.html#SERIAL_CONTROL_DEV" target="_blank" rel="noreferrer">SERIAL_CONTROL_DEV</a>):</p><table tabindex="0"><thead><tr><th>Device ID</th><th>Target</th></tr></thead><tbody><tr><td><code>0</code></td><td><code>TELEM1</code></td></tr><tr><td><code>1</code></td><td><code>TELEM2</code></td></tr><tr><td><code>2</code></td><td><code>GPS1</code></td></tr><tr><td><code>3</code></td><td><code>GPS2</code></td></tr><tr><td><code>4</code></td><td><code>TELEM3</code></td></tr><tr><td><code>5</code></td><td><code>TELEM4</code></td></tr><tr><td><code>20</code></td><td>ESC channel 0 (<a href="#bitbang">bitbang</a>)</td></tr><tr><td><code>21</code></td><td>ESC channel 1 (bitbang)</td></tr><tr><td><code>22</code></td><td>ESC channel 2 (bitbang)</td></tr><tr><td><code>23</code></td><td>ESC channel 3 (bitbang)</td></tr><tr><td><code>24</code></td><td>ESC channel 4 (bitbang)</td></tr><tr><td><code>25</code></td><td>ESC channel 5 (bitbang)</td></tr><tr><td><code>26</code></td><td>ESC channel 6 (bitbang)</td></tr><tr><td><code>27</code></td><td>ESC channel 7 (bitbang)</td></tr></tbody></table><p>The UART device path for each port (e.g. <code>/dev/ttyS1</code>) is taken from the board&#39;s corresponding Kconfig symbols, such as <code>CONFIG_BOARD_SERIAL_TEL1</code>, <code>CONFIG_BOARD_SERIAL_GPS1</code>, and so on. If the used device ID is not configured on the board, the driver logs a warning and rejects the message.</p><h2 id="uart-control" tabindex="-1">UART Control <a class="header-anchor" href="#uart-control" aria-label="Permalink to &quot;UART Control&quot;">​</a></h2><p>Normal UARTs such as those for telemetry and GPS are targeted using device IDs 0 to 5.</p><p>This feature requires only that the <a href="./../modules/modules_driver#serialpassthrough"><code>serialpassthrough</code> driver</a> is present in firmware (the KConfig key <code>CONFIG_DRIVERS_SERIALPASSTHROUGH=y</code> must be set). Note that the <code>PASSTHRU_EN</code> parameter need not be set.</p><h2 id="bitbang" tabindex="-1">ESC Channel Mode (Bitbang UART) <a class="header-anchor" href="#bitbang" aria-label="Permalink to &quot;ESC Channel Mode (Bitbang UART) {#bitbang}&quot;">​</a></h2><p>Device IDs 20–27 route through a software bit-bang UART on the ESC signal pin rather than a hardware UART. This is useful for communicating with ESCs that expose a UART telemetry or configuration port on their signal wire (such as BLHeli_32 passthrough, AM32, or ESC configuration tools).</p><p>Bitbang UART is implemented using a hardware timer and direct GPIO toggling. Due to interrupt latency, reliable operation is only guaranteed up to <strong>19200 baud</strong>.</p><p>Because only one hardware timer is used, only one ESC channel can be active at a time. When a request arrives for a different ESC channel, the driver stops the current instance and waits up to 100 ms for it to exit before starting the new one.</p><p>Bitbang UART support requires that both <code>CONFIG_DRIVERS_SERIALPASSTHROUGH=y</code> and <code>CONFIG_SERIALPASSTHROUGH_BITBANG=y</code> are set before building (the timer is selected with <code>CONFIG_UART_BITBANG_TIMER</code>, and defaults to <code>TIM13</code>). The <code>PASSTHRU_EN</code> parameter must be set to <code>1</code> and the device rebooted in order to enable this mode.</p><h2 id="bridge-application" tabindex="-1">Bridge Application <a class="header-anchor" href="#bridge-application" aria-label="Permalink to &quot;Bridge Application&quot;">​</a></h2><p><a href="https://github.com/PX4/PX4-Autopilot/blob/main/Tools/mavlink_serial_bridge.py" target="_blank" rel="noreferrer"><code>Tools/mavlink_serial_bridge.py</code></a> is a reference bridge application (Linux/macOS only): it connects to the vehicle over MAVLink, exposes a virtual serial port (a Unix PTY) to a serial tool on the host, such as an ESC configurator, and translates traffic bidirectionally.</p><p>The script supports all <a href="#device-ids">device IDs</a>, selected with its <code>--port</code> option:</p><table tabindex="0"><thead><tr><th><code>--port</code></th><th>Device ID</th><th>Target</th></tr></thead><tbody><tr><td><code>telem1</code></td><td><code>0</code></td><td><code>TELEM1</code></td></tr><tr><td><code>telem2</code></td><td><code>1</code></td><td><code>TELEM2</code></td></tr><tr><td><code>gps1</code></td><td><code>2</code></td><td><code>GPS1</code></td></tr><tr><td><code>gps2</code></td><td><code>3</code></td><td><code>GPS2</code></td></tr><tr><td><code>telem3</code></td><td><code>4</code></td><td><code>TELEM3</code></td></tr><tr><td><code>telem4</code></td><td><code>5</code></td><td><code>TELEM4</code></td></tr><tr><td><code>esc0</code>–<code>esc7</code></td><td><code>20</code>–<code>27</code></td><td>ESC channels 0–7</td></tr></tbody></table><p>Install its only dependency and run it, for example to bridge ESC channel 0:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pymavlink</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./Tools/mavlink_serial_bridge.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --connection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyUSB0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> esc0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --setup</span></span></code></pre></div><p><code>--connection</code> takes a <a href="https://mavlink.io/en/mavgen_python/#connection_string" target="_blank" rel="noreferrer">pymavlink connection string</a> for the link to the vehicle, such as a telemetry radio (<code>/dev/ttyUSB0</code>, with <code>--baud</code> if it isn&#39;t 57600) or a network link (<code>tcp:&lt;ip&gt;:&lt;port&gt;</code>, or <code>udpin:0.0.0.0:14550</code>). A <code>udp:127.0.0.1:&lt;port&gt;</code> string only receives MAVLink traffic sent to this machine, for example by a local MAVLink router.</p><p><code>--setup</code> sets <code>PASSTHRU_EN=1</code> and reboots the flight controller, so DShot/PWM outputs are not started until the next reboot (see <a href="#px4-configuration-esc-targets">PX4 Configuration (ESC targets)</a>). Use it only with <code>esc*</code> ports, and again after each reboot, since PX4 resets the parameter at boot. For <code>telem*</code> and <code>gps*</code> ports, leave out <code>--setup</code>: they don&#39;t need <code>PASSTHRU_EN</code>.</p><p>The script prints the PTY path it created (e.g. <code>/dev/pts/5</code>). Once it prints <code>Bridge running</code>, point any tool that expects a serial connection (ESC configurator, GPS/RTK utility, and so on) at that path. Run it with <code>-h</code> for the full list of options.</p><p>For <code>esc*</code> ports the UART baud rate is fixed at 19200 (the bitbang limit) and <code>--port-baud</code> is ignored.</p><p>Developers can create their own bridge application in another language if needed, following the protocol described below. Data written to the PTY would be sent as <code>SERIAL_CONTROL</code> messages with <code>SERIAL_CONTROL_FLAG_RESPOND | SERIAL_CONTROL_FLAG_EXCLUSIVE</code> set, and incoming <code>SERIAL_CONTROL</code> reply messages (with <code>FLAG_REPLY</code> set) would be written back to the PTY.</p><p>To initialise the passthrough, the bridge should send one <code>SERIAL_CONTROL</code> message with the target device ID, the desired UART baud rate in the <code>baudrate</code> field, and <code>count=0</code> (no payload), then wait approximately 2 seconds for PX4 to spawn the passthrough task before sending real traffic. For ESC bitbang mode (device IDs 20–27), the bridge must first set <code>PASSTHRU_EN=1</code> via <code>PARAM_SET</code>, confirm the <code>PARAM_VALUE</code> acknowledgement, send <code>MAV_CMD_PREFLIGHT_REBOOT_SHUTDOWN</code>, and wait for the FMU heartbeat to return before sending the init message — this ensures the DShot/PWM drivers are not running when the bitbang driver takes over the ESC signal pins.</p><h3 id="switching-devices-at-runtime" tabindex="-1">Switching Devices at Runtime <a class="header-anchor" href="#switching-devices-at-runtime" aria-label="Permalink to &quot;Switching Devices at Runtime&quot;">​</a></h3><p>The bridge reads commands from its standard input, so that a host tool that launches it as a subprocess can change the target device without restarting the bridge. This is mainly intended for tools that work through several ESCs in sequence, such as flashing or configuring each ESC channel in turn.</p><p>To switch, write a line in the following form to the bridge&#39;s stdin (or type it and press Enter when running it interactively):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SWITCH &lt;device_id&gt;</span></span></code></pre></div><p><code>&lt;device_id&gt;</code> is the numeric <a href="#device-ids">device ID</a> (for example <code>SWITCH 21</code> for ESC channel 1), not the <code>--port</code> name. Lines that are not valid <code>SWITCH</code> commands are ignored.</p><p>When a valid command is received, the bridge:</p><ol><li>Prints <code>Switching to device &lt;device_id&gt;</code>.</li><li>Sends a <code>SERIAL_CONTROL</code> init message (<code>count=0</code>) for the new device, using the same UART baud rate the bridge was started with.</li><li>Forwards all further PTY traffic to the new device, and discards replies that still arrive from the previous device.</li></ol><p>The PTY path does not change, so the host tool can keep its serial port open across the switch.</p><p>Note the following when using <code>SWITCH</code>:</p><ul><li>The bridge does not wait after sending the init message. Allow some time for PX4 to stop the previous instance and start the new one (up to 100 ms for ESC channels) before sending data.</li><li>The baud rate is not changed, so switching between ESC channels (19200 baud) works as expected, but switching between ESC and <code>telem*</code>/<code>gps*</code> targets keeps the original baud rate.</li><li><code>--setup</code> is only applied at startup. <code>PASSTHRU_EN</code> must already be enabled before you switch to an ESC channel.</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><h3 id="firmware-configuration-build-time" tabindex="-1">Firmware Configuration (Build-Time) <a class="header-anchor" href="#firmware-configuration-build-time" aria-label="Permalink to &quot;Firmware Configuration (Build-Time)&quot;">​</a></h3><p>The driver is enabled via <a href="./../hardware/porting_guide_config">Kconfig</a>. You will need to set the following key in your board:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONFIG_DRIVERS_SERIALPASSTHROUGH=y # Include the driver</span></span></code></pre></div><p>If you want to use ESC channel targets you must also set the following keys:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONFIG_SERIALPASSTHROUGH_BITBANG=y # ESC channel support (NuttX &amp; STM32 only)</span></span>
<span class="line"><span>CONFIG_UART_BITBANG_TIMER=13       # Timer instance (default TIM13)</span></span></code></pre></div><p>Then rebuild the firmware.</p><h3 id="px4-configuration-esc-targets" tabindex="-1">PX4 Configuration (ESC targets) <a class="header-anchor" href="#px4-configuration-esc-targets" aria-label="Permalink to &quot;PX4 Configuration (ESC targets)&quot;">​</a></h3><p>For ESC channel targets (only) you must also set <a href="./../advanced_config/parameter_reference#PASSTHRU_EN">PASSTHRU_EN</a> to <code>1</code> and reboot the vehicle.</p><p>This disables motor control after the reboot (the motor output drivers <code>dshot</code> and <code>pwm_out</code> are not started). This is required when you intend to use the ESC bitbang passthrough mode, because the bitbang driver and the DShot/PWM driver cannot share the same ESC signal pins.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The parameter auto-resets to <code>0</code> on the following reboot, so DShot/PWM output is automatically restored after power cycling.</p></div><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li><strong>Single sender:</strong> only one MAVLink sender is supported at a time. A single sender can communicate with multiple ports simultaneously, but replies are always routed back to the MAVLink channel that sent the most recent <code>SERIAL_CONTROL</code> message. This means that concurrent senders could interfere with each other&#39;s replies.</li><li><strong>ESC bitbang baud rate:</strong> maximum reliable baud rate is 19200. Higher rates may work but are not guaranteed.</li><li><strong>ESC channel exclusivity:</strong> only one ESC bitbang channel can be active at a time.</li><li><strong>Platform:</strong> bitbang UART is only available on NuttX with STM32F7/H7. Requesting ESC bitbang on an unsupported platform logs an error.</li><li><strong>Buffer size:</strong> each instance has a 1 kB receive and 1 kB transmit buffer. Frames larger than 1 kB will be truncated with a warning logged.</li></ul>`,51))])}const T=o(l,[["render",h]]);export{S as __pageData,T as default};
